  replace.Dock=DockStyle.Fill;replace.Text="Sustituir este NAM (con copia previa)";var replaceHost=new Panel{Dock=DockStyle.Fill};replaceHost.Controls.Add(replace);replaceHint.Dock=DockStyle.Fill;replaceHint.ForeColor=muted;replaceHost.Controls.Add(replaceHint);right.Controls.Add(replaceHost);summary.Dock=DockStyle.Fill;summary.ForeColor=accent;right.Controls.Add(summary);SetupButton(send,"Elige un destino",300);send.Dock=DockStyle.Fill;right.Controls.Add(send);help.Dock=DockStyle.Fill;help.ForeColor=muted;help.Text="El nivel se aplica al enviar. Después selecciona el Model indicado en la POD Go.";right.Controls.Add(help);
